/// The bounded read requests the VM can make of an opaque host file.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IoReadRequest {
    /// Read all remaining bytes.
    All,
    /// Read one line, optionally retaining its trailing newline.
    Line { keep_end: bool },
    /// Read at most this many bytes.
    Bytes(usize),
}

/// The origin used by an opaque host file seek operation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IoSeekWhence {
    /// Offset from the beginning of the file.
    Set,
    /// Offset from the current position.
    Current,
    /// Offset from the end of the file.
    End,
}

/// The buffering mode requested by a guest `file:setvbuf` call.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IoBufferMode {
    /// Disable buffering.
    None,
    /// Buffer until the host flushes or the buffer fills.
    Full,
    /// Flush at line boundaries where the host supports it.
    Line,
}

/// The standard `package.loadlib` failure location returned by a trusted
/// native-library bridge.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum NativeLibraryFailure {
    /// The host could not open the requested library.
    Open,
    /// The requested symbol is absent or dynamic loading is unavailable.
    Absent,
    /// The symbol was found but could not initialize the module.
    Init,
}

impl NativeLibraryFailure {
    const fn as_bytes(self) -> &'static [u8] {
        match self {
            Self::Open => b"open",
            Self::Absent => b"absent",
            Self::Init => b"init",
        }
    }
}

/// The bounded result of an embedding-owned `package.loadlib` lookup.
#[derive(Clone, Debug, PartialEq)]
pub enum NativeLibraryLoadResult {
    /// The bridge resolved and initialized a guest-callable module value.
    Loaded(Value),
    /// The bridge handled the lookup but could not produce a module value.
    /// Blu converts this into Lua's standard `(nil, message, where)` return.
    Unavailable {
        /// A bounded human-readable failure message.
        message: Vec<u8>,
        /// The standard Lua failure location.
        where_: NativeLibraryFailure,
    },
}

/// The standard stream requested from an embedding host.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IoStreamKind {
    /// Standard input.
    Stdin,
    /// Standard output.
    Stdout,
    /// Standard error.
    Stderr,
}

/// A host-provided broken-down calendar value for `os.date("*t")`.
///
/// The fields use Lua's public names and conventions: `weekday` is Sunday=1
/// through Saturday=7, and `yearday` is one-based. The host callback owns the
/// timezone and locale policy; the VM only validates and materializes the
/// bounded guest table.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CalendarDate {
    pub year: i64,
    pub month: i64,
    pub day: i64,
    pub hour: i64,
    pub minute: i64,
    pub second: i64,
    pub weekday: i64,
    pub yearday: i64,
    pub is_dst: bool,
}

impl CalendarDate {
    fn validate(self) -> Result<Self, RuntimeError> {
        if !(1..=12).contains(&self.month)
            || !(1..=31).contains(&self.day)
            || !(0..=23).contains(&self.hour)
            || !(0..=59).contains(&self.minute)
            || !(0..=60).contains(&self.second)
            || !(1..=7).contains(&self.weekday)
            || !(1..=366).contains(&self.yearday)
        {
            return Err(RuntimeError::InvalidRange {
                operation: "os.date calendar result",
            });
        }
        Ok(self)
    }
}

/// Host-facing input fields for `os.time(table)`.
///
/// The VM supplies Lua's defaults for omitted `hour`, `min`, and `sec`, while
/// retaining an omitted `isdst` as `None` so the host can apply its own DST
/// policy. The host owns timezone resolution and normalization policy.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CalendarDateInput {
    pub year: i64,
    pub month: i64,
    pub day: i64,
    pub hour: i64,
    pub minute: i64,
    pub second: i64,
    pub is_dst: Option<bool>,
}

/// Host result for a capability-backed `os.execute` call.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum OsExecuteResult {
    /// Whether a shell is available for the no-command form.
    Availability(bool),
    /// The normalized result of executing a command.
    Command {
        success: bool,
        kind: Vec<u8>,
        code: i64,
    },
}

/// Host-facing request for a capability-backed `os.exit` call.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct OsExitRequest {
    /// The process status requested by the guest.
    pub status: i64,
    /// Whether Lua requested close-before-exit (Lua 5.2+).
    pub close: bool,
}

impl CalendarDateInput {
    fn validate(self) -> Result<Self, RuntimeError> {
        if !(1..=12).contains(&self.month)
            || !(1..=31).contains(&self.day)
            || !(0..=23).contains(&self.hour)
            || !(0..=59).contains(&self.minute)
            || !(0..=60).contains(&self.second)
        {
            return Err(RuntimeError::InvalidRange {
                operation: "os.time calendar input",
            });
        }
        Ok(self)
    }
}

/// Host-owned state backing an opaque Lua file handle.
///
/// The VM never interprets the host resource. It only forwards bounded file
/// operations and retains the opaque value while the guest handle remains
/// reachable. The default operation implementations preserve compatibility
/// for embedders that only provide close semantics.
pub trait IoFile: Send + Sync {
    fn close(&self) -> Result<(), RuntimeError>;

    /// Reads according to a VM-parsed request. `None` represents EOF.
    fn read(&self, _request: IoReadRequest) -> Result<Option<Vec<u8>>, RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "io.read",
            feature: "host file read capability",
        })
    }

    /// Reads and consumes one host-parsed numeric token. `None` represents
    /// EOF or the absence of a numeric token.
    fn read_number(&self) -> Result<Option<Vec<u8>>, RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "io.read",
            feature: "host numeric file read capability",
        })
    }

    /// Writes one bounded byte sequence.
    fn write(&self, _bytes: &[u8]) -> Result<(), RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "io.write",
            feature: "host file write capability",
        })
    }

    /// Moves the current file position and returns the resulting offset.
    fn seek(&self, _whence: IoSeekWhence, _offset: i64) -> Result<u64, RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "io.seek",
            feature: "host file seek capability",
        })
    }

    /// Flushes pending host-side file writes.
    fn flush(&self) -> Result<(), RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "io.flush",
            feature: "host file flush capability",
        })
    }

    /// Selects host-side buffering for a file handle.
    fn set_buffering(&self, _mode: IoBufferMode, _size: Option<usize>) -> Result<(), RuntimeError> {
        Err(RuntimeError::UnsupportedLibraryFeature {
            function: "file.setvbuf",
            feature: "host file buffering capability",
        })
    }
}

/// Completion callback for a resumable `load` reader.
///
/// The callback runs after the reader has returned its final chunk. It is
/// deliberately runtime-owned so a language layer can compile the collected
/// source without teaching the VM about a particular compiler.
#[derive(Clone)]
pub struct LoadReaderCompletion(Arc<LoadReaderCallback>);

impl LoadReaderCompletion {
    pub fn new(
        callback: impl Fn(&mut Vm, &[u8]) -> Result<Vec<Value>, RuntimeError> + Send + Sync + 'static,
    ) -> Self {
        Self(Arc::new(callback))
    }

    pub fn complete(&self, vm: &mut Vm, source: &[u8]) -> Result<Vec<Value>, RuntimeError> {
        (self.0)(vm, source)
    }
}

impl fmt::Debug for LoadReaderCompletion {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("LoadReaderCompletion")
    }
}

