type BluDebugName = (Option<Arc<[u8]>>, Option<Arc<[u8]>>);

fn blu_metamethod_debug_name(name: &'static str) -> BluDebugName {
    let name = name.strip_prefix("__").unwrap_or(name);
    (
        Some(Arc::from(&b"metamethod"[..])),
        Some(Arc::from(name.as_bytes())),
    )
}

fn blu_call_function_register(instruction: &BluInstruction) -> Option<u16> {
    Some(match instruction {
        BluInstruction::SetListCall { function, .. }
        | BluInstruction::SetListCallVarargs { function, .. }
        | BluInstruction::SetListCallDynamic { function, .. }
        | BluInstruction::Call { function, .. }
        | BluInstruction::CallResults { function, .. }
        | BluInstruction::CallVarargsResults { function, .. }
        | BluInstruction::CallAllResults { function, .. }
        | BluInstruction::CallVarargsAllResults { function, .. }
        | BluInstruction::CallDynamicResults { function, .. }
        | BluInstruction::CallDynamicAllResults { function, .. }
        | BluInstruction::ReturnCall { function, .. }
        | BluInstruction::ReturnCallPrefix { function, .. }
        | BluInstruction::ReturnCallVarargs { function, .. }
        | BluInstruction::ReturnCallVarargsPrefix { function, .. }
        | BluInstruction::ReturnCallDynamic { function, .. }
        | BluInstruction::ReturnCallDynamicPrefix { function, .. } => *function,
        _ => return None,
    })
}

fn blu_call_argument_register(instruction: &BluInstruction, argument: u16) -> Option<u16> {
    let (first, count) = match instruction {
        BluInstruction::SetListCall {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::SetListCallVarargs {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::SetListCallDynamic {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::Call {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallVarargsResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallVarargsAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallDynamicResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallDynamicAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCall {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallPrefix {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallVarargs {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallVarargsPrefix {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallDynamic {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallDynamicPrefix {
            arguments,
            argument_count,
            ..
        } => (*arguments, *argument_count),
        _ => return None,
    };
    (argument < count)
        .then(|| first.checked_add(argument))
        .flatten()
}

fn blu_call_argument_debug_name(frame: &BluDebugFrame, value: &Value) -> BluDebugName {
    let Some(prototype) = frame.artifact.prototypes.get(frame.prototype) else {
        return (None, None);
    };
    let Some(instruction) = prototype.code.get(frame.pc) else {
        return (None, None);
    };
    let Some(argument) = blu_call_argument_register(instruction, 0) else {
        return (None, None);
    };
    if frame.registers.get(usize::from(argument)) != Some(value) {
        return (None, None);
    }
    let Ok(call_pc) = u32::try_from(frame.pc) else {
        return (None, None);
    };
    if let Some(local) = prototype.locals.iter().find(|local| {
        local.start_pc <= call_pc
            && call_pc < local.end_pc
            && (local.register == argument
                || frame
                    .registers
                    .get(usize::from(local.register))
                    .is_some_and(|local| local == value))
    }) {
        if local.name.is_empty() {
            return (None, None);
        }
        return (
            Some(Arc::from(&b"local"[..])),
            Some(Arc::from(local.name.as_slice())),
        );
    }
    let mut source_register = argument;
    for previous in prototype.code[..frame.pc].iter().rev() {
        match previous {
            BluInstruction::LoadGlobal { destination, name } if *destination == source_register => {
                let Some(BluConstant::String(name)) = usize::try_from(*name)
                    .ok()
                    .and_then(|index| prototype.constants.get(index))
                else {
                    return (None, None);
                };
                return (
                    Some(Arc::from(&b"global"[..])),
                    Some(Arc::from(name.as_slice())),
                );
            }
            BluInstruction::Move {
                destination,
                source,
            } if *destination == source_register => {
                source_register = *source;
            }
            _ => {}
        }
    }
    (None, None)
}

fn snapshot_blu_debug_frames(frames: &[BluDebugFrame]) -> Result<Vec<BluDebugFrame>, RuntimeError> {
    let mut snapshots = try_vec_with_capacity(frames.len(), "coroutine debug frames")?;
    for frame in frames {
        snapshots.push(BluDebugFrame {
            artifact: Arc::clone(&frame.artifact),
            prototype: frame.prototype,
            closure: frame.closure,
            pc: frame.pc,
            registers: Vec::new(),
            varargs: frame.varargs.clone(),
            namewhat: frame.namewhat.clone(),
            name: frame.name.clone(),
            istailcall: frame.istailcall,
        });
    }
    Ok(snapshots)
}

fn blu_call_arguments(instruction: &BluInstruction) -> Option<(u16, u16)> {
    Some(match instruction {
        BluInstruction::SetListCall {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::SetListCallVarargs {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::SetListCallDynamic {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::Call {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallVarargsResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallVarargsAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallDynamicResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::CallDynamicAllResults {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCall {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallPrefix {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallVarargs {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallVarargsPrefix {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallDynamic {
            arguments,
            argument_count,
            ..
        }
        | BluInstruction::ReturnCallDynamicPrefix {
            arguments,
            argument_count,
            ..
        } => (*arguments, *argument_count),
        _ => return None,
    })
}

fn blu_instruction_destination(instruction: &BluInstruction) -> Option<u16> {
    Some(match instruction {
        BluInstruction::LoadConstant { destination, .. }
        | BluInstruction::LoadGlobal { destination, .. }
        | BluInstruction::NewTable { destination }
        | BluInstruction::GetTable { destination, .. }
        | BluInstruction::Call { destination, .. }
        | BluInstruction::CallResults { destination, .. }
        | BluInstruction::CallVarargsResults { destination, .. }
        | BluInstruction::CallDynamicResults { destination, .. }
        | BluInstruction::NewClosure { destination, .. }
        | BluInstruction::GetUpvalue { destination, .. }
        | BluInstruction::Varargs { destination, .. }
        | BluInstruction::Move { destination, .. }
        | BluInstruction::Not { destination, .. }
        | BluInstruction::Negate { destination, .. }
        | BluInstruction::Length { destination, .. }
        | BluInstruction::Add { destination, .. }
        | BluInstruction::Subtract { destination, .. }
        | BluInstruction::Multiply { destination, .. }
        | BluInstruction::Divide { destination, .. }
        | BluInstruction::Modulo { destination, .. }
        | BluInstruction::Power { destination, .. }
        | BluInstruction::FloorDivide { destination, .. }
        | BluInstruction::BitwiseAnd { destination, .. }
        | BluInstruction::BitwiseOr { destination, .. }
        | BluInstruction::BitwiseExclusiveOr { destination, .. }
        | BluInstruction::ShiftLeft { destination, .. }
        | BluInstruction::ShiftRight { destination, .. }
        | BluInstruction::BitwiseNot { destination, .. }
        | BluInstruction::Concatenate { destination, .. }
        | BluInstruction::Equal { destination, .. }
        | BluInstruction::LessThan { destination, .. }
        | BluInstruction::LessEqual { destination, .. } => *destination,
        _ => return None,
    })
}

fn blu_lua55_condition_line(prototype: &BluPrototype, pc: usize) -> bool {
    if prototype.profile != SemanticProfile::Lua55 {
        return false;
    }
    let Some(line) = prototype
        .line_info
        .get(pc)
        .copied()
        .filter(|line| *line != 0)
    else {
        return false;
    };
    if pc == 0
        || prototype
            .line_info
            .get(pc - 1)
            .copied()
            .filter(|previous| *previous != 0)
            == Some(line)
    {
        return false;
    }
    let destination = match prototype.code.get(pc - 1) {
        Some(BluInstruction::CallResults { destination, .. })
        | Some(BluInstruction::CallVarargsResults { destination, .. })
        | Some(BluInstruction::CallDynamicResults { destination, .. }) => *destination,
        Some(BluInstruction::Call { destination, .. }) => *destination,
        _ => return false,
    };
    matches!(
        prototype.code.get(pc),
        Some(BluInstruction::JumpIfTruthy { condition, .. })
            | Some(BluInstruction::JumpIfFalsy { condition, .. })
            if *condition == destination
    )
}

fn blu_callee_debug_name(caller: &BluCaller) -> BluDebugName {
    if let Some(name) = &caller.debug_name {
        return name.clone();
    }
    blu_callee_debug_name_parts(
        &caller.artifact,
        caller.prototype,
        &caller.constants,
        &caller.registers,
        caller.pc,
    )
}

fn update_blu_debug_frame_metadata(
    frame: &mut BluDebugFrame,
    artifact: &Arc<BluArtifact>,
    prototype: usize,
    closure: Option<ClosureId>,
    pc: usize,
    names: BluDebugName,
) {
    frame.artifact = Arc::clone(artifact);
    frame.prototype = prototype;
    frame.closure = closure;
    frame.pc = pc;
    frame.namewhat = names.0;
    frame.name = names.1;
}

fn blu_callee_debug_name_parts(
    artifact: &BluArtifact,
    prototype_index: usize,
    constants: &[Value],
    registers: &[Value],
    pc: usize,
) -> BluDebugName {
    let Some(prototype) = artifact.prototypes.get(prototype_index) else {
        return (None, None);
    };
    let Some(call_pc) = pc.checked_sub(1) else {
        return (None, None);
    };
    let Some(instruction) = prototype.code.get(call_pc) else {
        return (None, None);
    };
    let Some(function) = blu_call_function_register(instruction) else {
        return (None, None);
    };
    let generic_for_iterator =
        blu_instruction_destination(instruction).is_some_and(|destination| {
            matches!(
                (
                    prototype.code.get(call_pc + 1),
                    prototype.code.get(call_pc + 2),
                    prototype.code.get(call_pc + 3),
                ),
                (
                    Some(BluInstruction::Move { source, .. }),
                    Some(BluInstruction::LoadConstant { .. }),
                    Some(BluInstruction::Equal { left, .. }),
                ) if *source == destination && *left == destination
            )
        });
    if generic_for_iterator {
        return (
            Some(Arc::from(&b"for iterator"[..])),
            Some(Arc::from(&b"for iterator"[..])),
        );
    }
    if let Ok(call_pc) = u32::try_from(call_pc)
        && let Some(local) = prototype.locals.iter().find(|local| {
            local.start_pc <= call_pc && call_pc < local.end_pc && local.register == function
        })
    {
        if local.name.is_empty() {
            return (None, None);
        }
        return (
            Some(Arc::from(&b"local"[..])),
            Some(Arc::from(local.name.as_slice())),
        );
    }
    let call_arguments = blu_call_arguments(instruction);
    let mut name = None;
    for (previous_pc, previous) in prototype.code[..call_pc].iter().enumerate().rev() {
        name = match previous {
            BluInstruction::LoadGlobal { destination, name } if *destination == function => {
                usize::try_from(*name)
                    .ok()
                    .and_then(|name| constants.get(name))
                    .and_then(|value| match value {
                        Value::String(name) => Some((b"global".as_slice(), Arc::clone(name))),
                        _ => None,
                    })
            }
            BluInstruction::GetTable {
                destination,
                table,
                key,
            } if *destination == function => {
                let key_is_local = u32::try_from(call_pc).ok().is_some_and(|call_pc| {
                    prototype.locals.iter().any(|local| {
                        local.register == *key
                            && local.start_pc <= call_pc
                            && call_pc < local.end_pc
                    })
                });
                let static_name = if key_is_local {
                    None
                } else {
                    prototype.code[..previous_pc]
                        .iter()
                        .rev()
                        .find_map(|instruction| match instruction {
                            BluInstruction::LoadConstant {
                                destination,
                                constant,
                            } if *destination == *key => constants
                                .get(usize::try_from(*constant).ok()?)
                                .and_then(|value| match value {
                                    Value::String(name) => Some(Arc::clone(name)),
                                    _ => None,
                                }),
                            _ => None,
                        })
                };
                let is_method = call_arguments
                    .and_then(|(arguments, argument_count)| {
                        (argument_count > 0).then(|| {
                            registers.get(usize::from(arguments))
                                == registers.get(usize::from(*table))
                        })
                    })
                    .unwrap_or(false);
                let (namewhat, name) = match static_name {
                    Some(name) if is_method => (b"method".as_slice(), name),
                    Some(name)
                        if matches!(
                            prototype.profile,
                            SemanticProfile::Lua52
                                | SemanticProfile::Lua53
                                | SemanticProfile::Lua54
                                | SemanticProfile::Lua55
                        ) && *table == 0 =>
                    {
                        (b"global".as_slice(), name)
                    }
                    Some(name) => (b"field".as_slice(), name),
                    None => (b"field".as_slice(), Arc::from(&b"?"[..])),
                };
                Some((namewhat, name))
            }
            BluInstruction::GetUpvalue {
                destination,
                upvalue,
            } if *destination == function => prototype
                .upvalue_debug
                .get(usize::from(*upvalue))
                .and_then(|debug| {
                    (!debug.name.is_empty())
                        .then(|| (b"upvalue".as_slice(), Arc::from(debug.name.as_slice())))
                }),
            _ => None,
        };
        if name.is_some() || blu_instruction_destination(previous) == Some(function) {
            break;
        }
    }
    let Some((namewhat, name)) = name else {
        return (None, None);
    };
    (Some(Arc::from(namewhat)), Some(name))
}

fn blu_direct_native_debug_name(
    artifact: &Arc<BluArtifact>,
    prototype_index: usize,
    constants: &[Value],
    registers: &[Value],
    pc: usize,
) -> Result<Option<BluDebugName>, RuntimeError> {
    let Some(prototype) = artifact.prototypes.get(prototype_index) else {
        return Ok(None);
    };
    let Some(instruction) = prototype.code.get(pc) else {
        return Ok(None);
    };
    let Some(function) = blu_call_function_register(instruction) else {
        return Ok(None);
    };
    if !matches!(
        registers.get(usize::from(function)),
        Some(Value::NativeFunction(_))
    ) {
        return Ok(None);
    }
    let Some(caller_pc) = pc.checked_add(1) else {
        return Ok(None);
    };
    Ok(Some(blu_callee_debug_name_parts(
        artifact,
        prototype_index,
        constants,
        registers,
        caller_pc,
    )))
}

