    /// Installs the host-authorized standard stream provider used by the
    /// profile-visible `io.stdin`, `io.stdout`, `io.stderr`, `io.read`,
    /// `io.write`, and `io.flush` surfaces. Stream handles are created when
    /// the provider is configured so direct table-field access has ordinary
    /// Lua table semantics.
    pub fn set_io_stream_opener(
        &mut self,
        opener: impl Fn(IoStreamKind) -> Result<Arc<dyn IoFile>, RuntimeError> + Send + Sync + 'static,
    ) {
        self.io_stream_opener = Some(Arc::new(opener));
        let roots = GcRoots::default();
        let io_table = match self.globals.get(&b"io"[..]) {
            Some(Value::Table(table)) => Some(*table),
            _ => None,
        };
        for (kind, name) in [
            (IoStreamKind::Stdin, &b"stdin"[..]),
            (IoStreamKind::Stdout, &b"stdout"[..]),
            (IoStreamKind::Stderr, &b"stderr"[..]),
        ] {
            let Ok(userdata) = self.ensure_io_stream(kind, &roots, "io stream setup") else {
                continue;
            };
            if let Some(io_table) = io_table {
                self.heap
                    .table_set(
                        io_table,
                        Value::String(Arc::from(name)),
                        Value::UserData(userdata),
                    )
                    .expect("io stream setup table is valid");
            }
        }
    }

