        let error = self.register_function(|vm, arguments| {
            let profile = vm.active_profile()?;
            let level = match arguments.get(1) {
                None | Some(Value::Nil) => 1,
                Some(value) => error_level_argument(value, profile).ok_or(RuntimeError::Type {
                    operation: "error",
                    expected: "integer",
                    actual: value.type_name(),
                })?,
            };
            let value = arguments.first().cloned().unwrap_or(Value::Nil);
            let add_source_prefix = level > 0
                && (profile != SemanticProfile::Luau || vm.protected_native_target_depth == 0);
            let value = if add_source_prefix {
                if let Value::String(message) = value {
                    if let Some(mut prefix) = vm.blu_error_prefix(level)? {
                        prefix.extend_from_slice(&message);
                        Value::String(Arc::from(prefix))
                    } else {
                        Value::String(message)
                    }
                } else {
                    value
                }
            } else {
                value
            };
            Err(RuntimeError::Raised(value))
        });
