        self.set_global(&b"error"[..], Value::NativeFunction(error));

        let assert = self.register_function(|vm, arguments| {
            let profile = vm.active_profile()?;
            let add_source_prefix =
                profile != SemanticProfile::Luau || vm.protected_native_target_depth == 0;
            let prefix_message = |message: Value| -> Result<Value, RuntimeError> {
                if !add_source_prefix {
                    return Ok(message);
                }
                let Value::String(message) = message else {
                    return Ok(message);
                };
                if let Some(mut prefix) = vm.blu_error_prefix(1)? {
                    prefix.extend_from_slice(&message);
                    Ok(Value::String(Arc::from(prefix)))
                } else {
                    Ok(Value::String(message))
                }
            };
            let Some(value) = arguments.first() else {
                return Err(RuntimeError::Raised(prefix_message(Value::String(
                    Arc::from(&b"missing argument #1"[..]),
                ))?));
            };
            if value.is_truthy() {
                try_clone_values(arguments, "assert results")
            } else {
                let message = arguments
                    .get(1)
                    .cloned()
                    .unwrap_or_else(|| Value::String(Arc::from(&b"assertion failed!"[..])));
                Err(RuntimeError::Raised(prefix_message(message)?))
            }
        });
