                    vm.gc_mode = if command == b"incremental" {
                        GcMode::Incremental
                    } else {
                        GcMode::Generational
                    };
                    Ok(vec![profiled_integral_math_result(
                        vm,
                        "collectgarbage",
                        0.0,
                    )?])
