    #[test]
    fn string_sub_uses_lua_byte_indices_and_reports_type_errors() {
        let mut vm = Vm::default();
        let sub = native(&vm, b"string", b"sub");
        let string = Value::String(Arc::from(&b"a\xc3\xa9z"[..]));
        let cases = [
            (
                vec![string.clone(), Value::Integer(2), Value::Integer(3)],
                b"\xc3\xa9".as_slice(),
            ),
            (vec![string.clone(), Value::Integer(-1)], b"z".as_slice()),
            (
                vec![string.clone(), Value::Integer(3), Value::Integer(2)],
                b"".as_slice(),
            ),
            (
                vec![string.clone(), Value::Integer(-99), Value::Integer(99)],
                b"a\xc3\xa9z".as_slice(),
            ),
        ];
        for (arguments, expected) in cases {
            assert_eq!(
                sub(&mut vm, &arguments),
                Ok(vec![Value::String(Arc::from(expected))])
            );
        }
        assert!(matches!(
            sub(&mut vm, &[Value::Boolean(false), Value::Integer(1)]),
            Err(RuntimeError::Type {
                operation: "string.sub",
                expected: "string",
                actual: "boolean",
            })
        ));
        assert!(matches!(
            sub(&mut vm, &[string, Value::String(Arc::from(&b"1"[..]))]),
            Err(RuntimeError::Type {
                operation: "string.sub",
                expected: "number",
                actual: "string",
            })
        ));
    }

    #[test]
    fn direct_string_transformations_reject_oversized_host_inputs_before_copying() {
        let mut vm = Vm::default();
        let oversized = Value::String(Arc::from(vec![b'A'; MAX_STRING_BYTES + 1]));
        let expected = RuntimeError::StringLimit {
            required: MAX_STRING_BYTES + 1,
            limit: MAX_STRING_BYTES,
        };

        for (name, arguments) in [
            (
                b"sub".as_slice(),
                vec![oversized.clone(), Value::Integer(1)],
            ),
            (b"reverse".as_slice(), vec![oversized.clone()]),
            (b"lower".as_slice(), vec![oversized.clone()]),
            (b"upper".as_slice(), vec![oversized.clone()]),
            (b"split".as_slice(), vec![oversized.clone()]),
        ] {
            assert_eq!(
                native(&vm, b"string", name)(&mut vm, &arguments),
                Err(expected.clone()),
                "string.{}",
                String::from_utf8_lossy(name)
            );
        }

        let Value::NativeFunction(tostring) = vm.global(b"tostring").unwrap() else {
            panic!("tostring is not a native function");
        };
        let tostring = vm.native_functions[tostring.0 as usize].clone();
        assert_eq!(tostring(&mut vm, &[oversized]), Err(expected));
    }

